-- ChubbyLu Bakery POS v0.12.0 — administrator expense tracking
create table if not exists public.expense_categories(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(shop_id,name));
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,expense_date date not null,category_id uuid not null references public.expense_categories(id) on delete restrict,description text not null,amount numeric(12,2) not null check(amount>0),payment_method text not null check(payment_method in('cash','card','bank','other')),vendor text,reference text,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create index if not exists expenses_shop_date_idx on public.expenses(shop_id,expense_date desc);alter table public.expense_categories enable row level security;alter table public.expenses enable row level security;
create policy expense_categories_admin_select on public.expense_categories for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());create policy expenses_admin_select on public.expenses for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
alter table public.cash_drawer_transactions add column if not exists expense_id uuid references public.expenses(id) on delete restrict;
create unique index if not exists drawer_expense_once on public.cash_drawer_transactions(expense_id) where expense_id is not null;

create or replace function public.create_expense(p_expense_date date,p_category_name text,p_description text,p_amount numeric,p_payment_method text,p_vendor text default null,p_reference text default null) returns uuid language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_category uuid;v_expense uuid;v_session uuid;
begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_expense_date is null or p_expense_date>current_date then raise exception 'Expense date cannot be in the future';end if;if nullif(trim(p_category_name),'') is null or nullif(trim(p_description),'') is null or p_amount is null or p_amount<=0 then raise exception 'Category, description, and positive amount are required';end if;if p_payment_method not in('cash','card','bank','other') then raise exception 'Invalid payment method';end if;
insert into public.expense_categories(shop_id,name) values(v_shop,trim(p_category_name)) on conflict(shop_id,name) do update set active=true returning id into v_category;
insert into public.expenses(shop_id,expense_date,category_id,description,amount,payment_method,vendor,reference,created_by) values(v_shop,p_expense_date,v_category,trim(p_description),round(p_amount,2),p_payment_method,nullif(trim(p_vendor),''),nullif(trim(p_reference),''),auth.uid()) returning id into v_expense;
if p_payment_method='cash' then select id into v_session from public.cash_drawer_sessions where shop_id=v_shop and status='open' for update;if v_session is not null then insert into public.cash_drawer_transactions(shop_id,session_id,transaction_type,amount,reason,expense_id,performed_by) values(v_shop,v_session,'cash_out',-round(p_amount,2),'Expense: '||trim(p_description),v_expense,auth.uid());end if;end if;return v_expense;end $$;

create or replace function public.get_expenses(p_from date,p_to date) returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'Invalid expense date range';end if;return jsonb_build_object('categories',(select coalesce(jsonb_agg(name order by name),'[]'::jsonb) from public.expense_categories where shop_id=v_shop and active),'expenses',(select coalesce(jsonb_agg(to_jsonb(x) order by x.expense_date desc,x.created_at desc),'[]'::jsonb) from(select e.id,e.expense_date,c.name category_name,e.description,e.amount,e.payment_method,e.vendor,e.reference,e.created_at,coalesce(sp.display_name,'Former staff') created_by_name from public.expenses e join public.expense_categories c on c.id=e.category_id left join public.staff_profiles sp on sp.user_id=e.created_by and sp.shop_id=e.shop_id where e.shop_id=v_shop and e.expense_date between p_from and p_to)x));end $$;
revoke all on function public.create_expense(date,text,text,numeric,text,text,text) from public;revoke all on function public.get_expenses(date,date) from public;grant execute on function public.create_expense(date,text,text,numeric,text,text,text) to authenticated;grant execute on function public.get_expenses(date,date) to authenticated;

-- Add all expenses (including non-cash) to the unified audit output.
create or replace function public.get_audit_log(p_from timestamptz,p_to timestamptz,p_limit int default 500) returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_limit int:=least(greatest(coalesce(p_limit,500),1),500);begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_from is null or p_to is null or p_to<p_from or p_to-p_from>interval '366 days' then raise exception 'Invalid audit date range';end if;return(select coalesce(jsonb_agg(to_jsonb(x) order by x.event_time desc),'[]'::jsonb) from(
select a.id,a.created_at event_time,'staff'::text category,a.action,coalesce(sp.display_name,'System') actor_name,coalesce(tp.display_name,a.target_email,'Staff account') target,jsonb_build_object('old_role',a.old_role,'new_role',a.new_role,'old_active',a.old_active,'new_active',a.new_active) details from public.staff_access_audit a left join public.staff_profiles sp on sp.user_id=a.performed_by and sp.shop_id=a.shop_id left join public.staff_profiles tp on tp.user_id=a.target_user_id and tp.shop_id=a.shop_id where a.shop_id=v_shop and a.created_at between p_from and p_to
union all select t.id,t.created_at,'cash_drawer',t.transaction_type,coalesce(sp.display_name,'System'),'Drawer shift '||left(t.session_id::text,8),jsonb_build_object('amount',t.amount,'reason',t.reason,'receipt_number',s.receipt_number) from public.cash_drawer_transactions t left join public.staff_profiles sp on sp.user_id=t.performed_by and sp.shop_id=t.shop_id left join public.sales s on s.id=t.sale_id where t.shop_id=v_shop and t.created_at between p_from and p_to
union all select r.id,r.created_at,'sale_adjustment',r.refund_type,coalesce(sp.display_name,'System'),'Receipt #'||s.receipt_number,jsonb_build_object('total',r.total,'reason',r.reason,'restocked',r.restocked,'approved_by',ap.display_name) from public.sale_refunds r join public.sales s on s.id=r.sale_id left join public.staff_profiles sp on sp.user_id=r.processed_by and sp.shop_id=r.shop_id left join public.staff_profiles ap on ap.user_id=r.approved_by and ap.shop_id=r.shop_id where r.shop_id=v_shop and r.created_at between p_from and p_to
union all select i.id,i.created_at,'inventory','stock_adjustment',coalesce(sp.display_name,'System'),p.name,jsonb_build_object('quantity_change',i.delta,'reason',i.reason) from public.inventory_adjustments i join public.products p on p.id=i.product_id left join public.staff_profiles sp on sp.user_id=i.created_by and sp.shop_id=i.shop_id where i.shop_id=v_shop and i.created_at between p_from and p_to
union all select rr.id,rr.created_at,'receipt','receipt_reprint',coalesce(sp.display_name,'System'),'Receipt #'||s.receipt_number,jsonb_build_object('sale_id',rr.sale_id) from public.receipt_reprints rr join public.sales s on s.id=rr.sale_id left join public.staff_profiles sp on sp.user_id=rr.reprinted_by and sp.shop_id=rr.shop_id where rr.shop_id=v_shop and rr.created_at between p_from and p_to
union all select e.id,e.created_at,'expense','expense_recorded',coalesce(sp.display_name,'System'),c.name||': '||e.description,jsonb_build_object('amount',e.amount,'payment_method',e.payment_method,'vendor',e.vendor,'reference',e.reference) from public.expenses e join public.expense_categories c on c.id=e.category_id left join public.staff_profiles sp on sp.user_id=e.created_by and sp.shop_id=e.shop_id where e.shop_id=v_shop and e.created_at between p_from and p_to
order by event_time desc limit v_limit)x);end $$;
